query.postgres:
select product_name, unit_price
from products
where unit_price > 50;

select country
from customers
order by country;

select distinct country
from customers
order by country;

select company_name, region
from customers
order by customer_id;

select 7 / 2 as whole,
  round(7 / 2.0, 1) as exact,
  7 % 2 as remainder;

query.mysql:
select 7 div 2 as whole,
  round(7 / 2, 1) as exact,
  7 % 2 as remainder;
